16	pub(crate) struct EmbeddedValueReferencesBuilder {
17	    references: FxHashMap<TextRange, TokenText>,
18	}
19	
20	impl EmbeddedValueReferences {
21	    pub(crate) fn builder(&self) -> EmbeddedValueReferencesBuilder {
22	        EmbeddedValueReferencesBuilder::new()
23	    }
24	
25	    pub(crate) fn finish(&mut self, builder: EmbeddedValueReferencesBuilder) {
