30	impl EmbeddedValueReferencesBuilder {
31	    fn new() -> Self {
32	        Self {
33	            references: FxHashMap::default(),
34	        }
35	    }
36	
37	    /// Visit a non-source snippet to track value references
38	    pub(crate) fn visit_non_source_snippet(&mut self, root: &AnyJsRoot) {
39	        let preorder = root.syntax().preorder();
40	
41	        for event in preorder {
42	            match event {
43	                WalkEvent::Enter(node) => {
44	                    if let Some(reference) = JsReferenceIdentifier::cast_ref(&node) {
45	                        self.visit_reference_identifier(reference);
46	                    } else if let Some(member) = JsStaticMemberExpression::cast_ref(&node) {
47	                        self.visit_static_member_expression(member);
48	                    }
49	                }
50	                WalkEvent::Leave(_) => {}
51	            }
52	        }
53	    }
54	
55	    /// Visit an HTML root to track component element names as value references.
56	    ///
57	    /// This extracts component names from Vue/Svelte templates like:
58	    /// - `<Component />` → tracks `Component`
59	    /// - `<AvatarPrimitive.Fallback>` → tracks `AvatarPrimitive`
60	    pub(crate) fn visit_html_root(&mut self, root: &HtmlRoot) {
61	        for node in root.syntax().descendants() {
62	            // Check HtmlElement: <Component>...</Component>
63	            if let Some(element) = HtmlElement::cast_ref(&node) {
64	                self.visit_html_element(&element);
65	            }
66	
67	            // Check HtmlSelfClosingElement: <Component />
68	            if let Some(element) = HtmlSelfClosingElement::cast_ref(&node) {
69	                self.visit_html_self_closing_element(&element);
70	            }
71	        }
72	    }
73	
74	    fn visit_html_element(&mut self, element: &HtmlElement) -> Option<()> {
75	        // Skip script and style tags - these are not component references
76	        if element.is_script_tag() || element.is_style_tag() {
77	            return None;
78	        }
79	
80	        let opening = element.opening_element().ok()?;
81	        let name = opening.name().ok()?;
82	
83	        self.track_component_reference(&name);
84	
85	        Some(())
86	    }
87	
88	    fn visit_html_self_closing_element(&mut self, element: &HtmlSelfClosingElement) -> Option<()> {
89	        let name = element.name().ok()?;
90	
91	        self.track_component_reference(&name);
92	
93	        Some(())
94	    }
95	
96	    /// Track a component name as a value reference
97	    fn track_component_reference(&mut self, name: &AnyHtmlTagName) {
98	        match name {
99	            AnyHtmlTagName::HtmlComponentName(component) => {
100	                // Track simple component: <Component>
101	                if let Ok(token) = component.value_token() {
102	                    self.references
103	                        .insert(token.text_trimmed_range(), token.token_text_trimmed());
104	                }
105	            }
106	            AnyHtmlTagName::HtmlMemberName(member) => {
107	                // Track the base component from member expression: <Component.Member>
108	                if let Ok(object) = member.object() {
109	                    self.track_component_object(&object);
110	                }
111	            }
112	            AnyHtmlTagName::HtmlTagName(_) => {
113	                // Regular HTML tag, don't track
114	            }
115	        }
116	    }
117	
118	    /// Track the object part of a member expression
119	    fn track_component_object(&mut self, object: &AnyHtmlComponentObjectName) {
120	        match object {
121	            AnyHtmlComponentObjectName::HtmlTagName(tag) => {
122	                // For member expressions starting with lowercase (unusual but possible)
123	                if let Ok(token) = tag.value_token() {
124	                    self.references
125	                        .insert(token.text_trimmed_range(), token.token_text_trimmed());
126	                }
127	            }
128	            AnyHtmlComponentObjectName::HtmlComponentName(component) => {
129	                // Track the component name
130	                if let Ok(token) = component.value_token() {
131	                    self.references
132	                        .insert(token.text_trimmed_range(), token.token_text_trimmed());
133	                }
134	            }
135	            AnyHtmlComponentObjectName::HtmlMemberName(member) => {
136	                // Nested member - track its object recursively
137	                // e.g., A.B.C - track A
138	                if let Ok(object) = member.object() {
139	                    self.track_component_object(&object);
140	                }
141	            }
142	        }
143	    }
144	
145	    fn visit_reference_identifier(&mut self, reference: JsReferenceIdentifier) -> Option<()> {
146	        let usage = AnyJsIdentifierUsage::from(reference.clone());
147	        if usage.is_only_type() {
148	            return None;
149	        }
150	        let name_token = reference.value_token().ok()?;
151	        self.references.insert(
152	            name_token.text_trimmed_range(),
153	            name_token.token_text_trimmed(),
154	        );
155	        Some(())
156	    }
157	
158	    fn visit_static_member_expression(&mut self, member: JsStaticMemberExpression) -> Option<()> {
159	        let object = member.object().ok()?;
160	        if let Some(reference) = object.as_js_reference_identifier() {
161	            self.visit_reference_identifier(reference.clone())?;
162	        }
163	        Some(())
164	    }
165	}
