286	        // TODO: This should be extracted to a dedicated function, maybe in biome_fs
287	        // because the same logic is also used in JsFileSource::try_from
288	        // and we may support more and more extensions with more than one dots.
289	        let extension = &match filename {
290	            // Ignore files are extensionless files, so they need to be handled in particular way
291	            Some(filename) if filename == GIT_IGNORE_FILE_NAME || filename == IGNORE_FILE_NAME => {
292	                return Ok(Self::Ignore);
293	            }
294	            Some(filename) if filename.ends_with(".d.ts") => Cow::Borrowed("d.ts"),
295	            Some(filename) if filename.ends_with(".d.mts") => Cow::Borrowed("d.mts"),
296	            Some(filename) if filename.ends_with(".d.cts") => Cow::Borrowed("d.cts"),
297	            _ => path
298	                .extension()
299	                // We assume the file extensions are case-insensitive.
300	                // Thus, we normalize the extension to lowercase.
301	                .map(|ext| ext.to_ascii_lowercase_cow())
302	                .ok_or(FileSourceError::MissingFileExtension)?,
303	        };
304	
305	        Self::try_from_extension(extension.as_ref(), experimental_full_html_support)
306	    }
